type WorldState = {
  entities: Record<string, string>;
};

const initialState: WorldState = {
  entities: {
    Zef: "idle",
    Tal: "idle",
  },
};

const kindle = (state: WorldState, entities: string[]): WorldState => {
  const nextEntities = { ...state.entities };
  for (const entity of entities) {
    nextEntities[entity] = "pex";
  }
  return { entities: nextEntities };
};

export const protocol: WorldProtocol<WorldState> = {
  reset(): WorldState {
    return {
      entities: { ...initialState.entities },
    };
  },

  applyOperation(state, operationDisplayName) {
    switch (operationDisplayName) {
      case "kindleZef":
        return { success: true, newState: kindle(state, ["Zef"]) };
      case "kindleTal":
        return { success: true, newState: kindle(state, ["Tal"]) };
      case "kindleBoth":
        return { success: true, newState: kindle(state, ["Zef", "Tal"]) };
      default:
        return {
          success: false,
          error: `Unknown operation: ${operationDisplayName}`,
        };
    }
  },

  getEntityState(state, entityDisplayName) {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state.entities };
  },
};
